// src/handler.ts
import { URLExt } from '@jupyterlab/coreutils';
import { ServerConnection } from '@jupyterlab/services';

/**
 * Call the backend endpoint to retrieve the markdown.
 */
export async function requestAPI<T>(endpoint: string): Promise<T> {
  const settings = ServerConnection.makeSettings();
  const requestUrl = URLExt.join(settings.baseUrl, 'bearborg-about', endpoint);

  const response = await ServerConnection.makeRequest(requestUrl, {}, settings);
  if (!response.ok) {
    throw new Error(`Error fetching ${endpoint}: ${response.statusText}`);
  }
  return response.json() as Promise<T>;
}
